pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // The reference pays out the FULL balance; the mutant pays only 1 wei.
    // Any funded withdrawal from the owner must leave the contract empty.
    function testFuzz_property(uint256 amount) public {
        // Keep amount admissible but wide: any withdrawable balance above 1 wei
        // distinguishes correct (drain-all) from buggy (drain-1).
        amount = bound(amount, 2, type(uint256).max / 2);

        // Fund the contract directly; the owner is this test contract (deployer).
        vm.deal(address(c), amount);

        // Owner calls withdraw; the payout goes to this contract, which accepts ETH.
        vm.prank(address(this));
        c.withdraw();

        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}

