pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(amount < type(uint256).max / 2);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        // fund the contract with a fuzzed deposit from a fuzzed actor
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent, "deposit failed");

        // owner (deployer = this contract) withdraws
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // GENERAL RULE: a successful owner withdraw() must strictly reduce the
        // contract's balance (funds were transferred out to the Owner).
        assertTrue(ok && address(c).balance < amount);
    }
}

