pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address funder) public {
        // 1. wide admissible domain: any external funder, any positive amount
        vm.assume(funder != address(c));
        vm.assume(funder != address(this));
        amount = bound(amount, 1, type(uint128).max);

        // 2. fund the contract through its public payable receive
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        uint256 cBalBefore = address(c).balance;
        uint256 ownerBalBefore = address(this).balance;

        // 3. drive c through withdraw (Owner is this test contract, the deployer)
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // General rule: if a withdraw by the Owner succeeds, all ETH must have
        // actually left the contract AND the Owner must have been credited it.
        assertTrue(
            !ok || (address(c).balance == 0 && address(this).balance == ownerBalBefore + cBalBefore),
            "successful owner withdraw must pay out the entire balance to the Owner"
        );
    }
}

