pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor.code.length == 0);
        vm.assume(address(actor) != address(c));
        vm.assume(address(c).balance + amount <= type(uint256).max);

        // Make the fuzzed amount equal to the contract's balance exactly.
        vm.deal(address(c), amount);
        vm.deal(actor, amount);
        uint256 before = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.multiplicate{value: amount}(actor) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: when msg.value == address(c).balance, multiplicate is a no-op:
        // it succeeds and leaves the contract balance untouched.
        assertTrue(ok && address(c).balance == before);
    }
}

