contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(uint256 amount) public
    {
        require(address(this).balance >= amount);
        c.withdraw(); // ensure c starts empty (owner is the original deployer of C)
        c.multiplicate(address(this));
        address(c).call{value: 0}("");
        // fund c through its receive via a self-call pattern: use Command with empty data to c? not allowed self-send.
        // Instead: send ether by calling c's multiplicate-like path is state-dependent; use receive via low-level top-level call.
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        require(address(c).balance >= amount);
        c.withdraw();
        assert(address(c).balance == 0);
    }

    fallback() external payable {}
}

